import React from 'react';
import { Row, Col } from 'reactstrap';
import { employeeTableHead } from 'variables/general';
import { formUsernameFromEmail, makeSubText, usernameTextColor } from '../../../utils/commonFunc';
import { employeesStatic } from '../../../config/constants';
import CustomButton from '../../../components/CustomButton.jsx';
import CollapseTable from '../Common/CollapseTable.jsx';
import { ActiveSpan, DeactiveSpan } from '../Common/StatusBadges.jsx';

// Moved as-is from the old Teachers page (views/admin/Employee/EmployeePage.jsx) - same
// CollapseTable, same columns, same Edit-only row action, same per-row "expand to see assigned
// subjects" preview. Only the Import button and the surrounding page chrome changed homes.
// teacherList is now the server-side, profession-filtered flat list (see SchoolStaffHubPage's
// fetchTeachers) rather than the old paginated employeesData - hidePagination below since this
// list is no longer server-paginated.
const TeacherStaffPanel = ({
  teacherList,
  empSubjectList,
  isCollapseOpen,
  isEmpAssignFetching,
  isLoading,
  onAdd,
  onEdit,
  onFetchViewData,
  onImport,
}) => (
  <>
    <Row>
      <Col />
      <Col sm={6} md={6} lg={6}>
        <CustomButton className="mb-3" style={{ float: 'right' }} onClick={onAdd} name={`Add ${employeesStatic}`} />
        <CustomButton
          className="mb-3 mr-2"
          style={{ float: 'right' }}
          variant="outlined"
          onClick={onImport}
          name={`Import ${employeesStatic}`}
        />
      </Col>
    </Row>
    <CollapseTable
      tableHeaders={employeeTableHead}
      tableBodyData={{
        content: (teacherList || []).map(el => ({
          ...el,
          name: (
            <span>
              <div>{`${el.name} (${el.code})`}</div>
              <div style={{ color: usernameTextColor }}>{formUsernameFromEmail(el.email)}</div>
            </span>
          ),
          phoneNumber: el?.phoneNumber,
          designation: el.designation,
          status: el.status ? <ActiveSpan status={el.status} /> : <DeactiveSpan status={el.status} />,
        })),
      }}
      bodyColumns={['name', 'phoneNumber', 'designation', 'status', 'action']}
      dropDownActions={['edit']}
      idName="employeeId"
      fetchItem={onEdit}
      hidePagination={true}
      fetchViewData={onFetchViewData}
      collapseViewHeading="Assigned Subjects"
      collapseViewHeaders={['name', 'courseName']}
      collapseViewColumns={['Subject Name & Code', 'Course Name & Code']}
      collapseViewTableList={empSubjectList?.map(item => ({
        subjectCode: item?.subject?.subjectCode,
        name: (
          <>
            {item?.subject?.name} {makeSubText(item?.subject?.subjectCode)}
          </>
        ),
        courseCode: item?.subject?.course?.code,
        courseName: (
          <>
            {item?.subject?.course?.name} {makeSubText(item?.subject?.course?.code)}
          </>
        ),
      }))}
      isCollapseOpen={isCollapseOpen}
      isCollapseLoading={isEmpAssignFetching}
      isLoading={isLoading}
    />
  </>
);

export default TeacherStaffPanel;
