import React from 'react';
import { Row, Col } from 'reactstrap';
import { formUsernameFromEmail, usernameTextColor } from '../../../utils/commonFunc';
import CustomButton from '../../../components/CustomButton.jsx';
import MuiTable from '../Common/MuiTable.jsx';
import { ActiveSpan, DeactiveSpan } from '../Common/StatusBadges.jsx';

const WORKER_TABLE_HEAD = ['Name & Code', 'Phone', 'Designation', 'Status', 'Action'];

// New module (Workers didn't have any dedicated admin UI before) - same generic Employee CRUD
// the Teachers panel uses, just profession-filtered to NON_TEACHING and with Add/Delete wired in,
// which is what was actually missing for admins to bring workers into the system at all.
const WorkerStaffPanel = ({ workerList, isLoading, onAdd, onEdit, onDelete }) => (
  <>
    <Row>
      <Col />
      <Col sm={6} md={6} lg={6}>
        <CustomButton className="mb-3" style={{ float: 'right' }} onClick={onAdd} name="Add Worker" />
      </Col>
    </Row>
    <MuiTable
      tableHeaders={WORKER_TABLE_HEAD}
      tableBodyData={{
        content: (workerList || []).map(el => ({
          ...el,
          name: (
            <span>
              <div>{`${el.name} (${el.code})`}</div>
              <div style={{ color: usernameTextColor }}>{formUsernameFromEmail(el.email)}</div>
            </span>
          ),
          phoneNumber: el?.phoneNumber,
          designation: el.designation,
          status: el.status ? <ActiveSpan status={el.status} /> : <DeactiveSpan status={el.status} />,
        })),
      }}
      bodyColumns={['name', 'phoneNumber', 'designation', 'status', 'action']}
      dropDownActions={['edit', 'delete']}
      idName="employeeId"
      fetchItem={onEdit}
      deleteItem={onDelete}
      hidePagination={true}
      isLoading={isLoading}
    />
  </>
);

export default WorkerStaffPanel;
