import React from 'react';
import { connect } from 'react-redux';
import { Paper, Tab, Tabs } from '@material-ui/core';
import SchoolIcon from '@material-ui/icons/School';
import WorkIcon from '@material-ui/icons/Work';
import colors from '../../../config/colors';
import {
  fetchSchoolEmployeesApi,
  saveEmployeeService,
  fetchEmployeeService,
  updateEmployeeService,
  deleteEmployeeService,
} from '../../../actions/admin/employees';
import { fetchEmployeeSubjectsService } from '../../../actions/admin/subjects';
import { uploadDataService } from '../../../actions/admin/reports';
import { getGlobalSchoolUtils, getLocalStore, setLocalStore, formResMessage } from '../../../utils/commonFunc';
import { showToast } from '../../../actions/admin/auth';
import { store } from '../../../index';
import EmployeeFormModal from '../Employee/components/EmployeeFormModal.jsx';
import ImportEmployeesModal from '../Employee/components/ImportEmployeeModal.jsx';
import TeacherStaffPanel from './TeacherStaffPanel.jsx';
import WorkerStaffPanel from './WorkerStaffPanel.jsx';
import PeopleCountCards from '../Common/PeopleCountCards.jsx';

const ACTIVE_TAB_STORE_KEY = 'schoolStaffActiveTab';

// Deliberately not built on employeeStatic/employeesStatic (the configurable Teacher label) -
// "School Staffs" and its Workers tab are meant to read the same regardless of what a school
// calls its teaching staff.
const PAGE_TABS = [
  { key: 'teachers', label: 'Teachers', icon: <SchoolIcon /> },
  { key: 'workers', label: 'Workers', icon: <WorkIcon /> },
];

class SchoolStaffHubPage extends React.Component {
  state = {
    schoolId: 0,
    activeTab: getLocalStore(ACTIVE_TAB_STORE_KEY) || 'teachers',
    isCollapseOpen: {},
    isEmpAssignFetching: false,
    teacherList: [],
    workerList: [],
    employeesFetching: false,
    workersFetching: false,
    isModalOpen: false,
    editingEmployee: null,
    formDefaultProfession: 'TEACHING',
    isImportModalOpen: false,
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchTeachers();
        this.fetchWorkers();
      });
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  showWarning = (message, type) => store.dispatch(showToast(message, type));

  changeTab = (event, tabIndex) => {
    const activeTab = PAGE_TABS[tabIndex].key;
    setLocalStore(ACTIVE_TAB_STORE_KEY, activeTab);
    this.setState({ activeTab });
  };

  // Teachers and Workers both fetch through the plain (non-redux) API function, into their own
  // local state, rather than through the shared employeeList redux slot Staff Attendance uses -
  // this page fetches both lists eagerly on mount (not lazily per tab), so sharing one redux key
  // between them would mean whichever fetch resolves second clobbers the other's data. Filtered
  // server-side by the BE's own profession param - no client-side designation-text guessing.
  fetchTeachers = async () => {
    this.setState({ employeesFetching: true });
    const teacherList = await fetchSchoolEmployeesApi({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
      profession: 'TEACHING',
    });
    this.setState({ teacherList: teacherList || [], employeesFetching: false });
  };

  fetchWorkers = async () => {
    this.setState({ workersFetching: true });
    const workerList = await fetchSchoolEmployeesApi({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
      profession: 'NON_TEACHING',
    });
    this.setState({ workerList: workerList || [], workersFetching: false });
  };

  openAddModal = profession => {
    this.setState({ editingEmployee: null, formDefaultProfession: profession, isModalOpen: true });
  };

  openEditModal = employeeId => {
    return this.props.fetchEmployee({ employeeId, token: this.props.loggedUserToken }).then(() => {
      this.setState({ editingEmployee: this.props.employee, isModalOpen: true });
    });
  };

  closeModal = () => this.setState({ isModalOpen: false, editingEmployee: null });

  saveEmployee = data => {
    data.employerOrgId = this.state.schoolId;
    return this.props.saveEmployee({ postData: data, token: this.props.loggedUserToken });
  };

  updateEmployee = data => {
    return this.props.updateEmployee({
      employeeId: data.employeeId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  employeeUpdateSuccess = actionParam => {
    const roleWord =
      this.state.formDefaultProfession === 'NON_TEACHING' || this.state.editingEmployee?.profession === 'NON_TEACHING'
        ? 'Worker'
        : 'Teacher';
    this.setState({ isModalOpen: false, editingEmployee: null });
    this.showWarning(
      actionParam === 'add' ? `${roleWord} added successfully` : `${roleWord} updated successfully`,
      'success'
    );
    this.fetchTeachers();
    this.fetchWorkers();
  };

  importModalOpen = () => this.setState({ isImportModalOpen: true });

  importModalClose = () => this.setState({ isImportModalOpen: false });

  uploadEmployeesData = formData => {
    return this.props.uploadEmployeesData({
      schoolId: this.state.schoolId,
      formData,
      token: this.props.loggedUserToken,
      uploadType: 'employees',
    });
  };

  uploadSuccess = () => {
    this.setState({ isImportModalOpen: false });
    this.showWarning('Teacher data uploaded successfully', 'success');
    this.fetchTeachers();
  };

  fetchEmployeeAssignedSubjects = async (employeeId, isOpen) => {
    this.setState({ isCollapseOpen: { [employeeId]: isOpen }, isEmpAssignFetching: true });
    await this.props.fetchEmployeeSubjects({ employeeId, token: this.props.loggedUserToken });
    this.setState({ isEmpAssignFetching: false });
  };

  // No confirm-dialog of our own here - MuiTable's row action menu (see WorkerStaffPanel's
  // dropDownActions={['edit', 'delete']}) already confirms via its own ConfirmModal before ever
  // calling deleteItem, so this only ever runs after the admin has already said yes once.
  deleteWorker = employeeId => {
    return this.props
      .deleteEmployee({ employeeId, token: this.props.loggedUserToken })
      .then(() => {
        this.showWarning('Worker deleted successfully', 'success');
        this.fetchWorkers();
      })
      .catch(err => this.showWarning(formResMessage(err), 'error'));
  };

  render() {
    const { activeTab, teacherList, workerList } = this.state;
    const activeIndex = PAGE_TABS.findIndex(tab => tab.key === activeTab);
    const { empSubjectList } = this.props;

    return (
      <div className="content">
        <Paper square style={{ marginBottom: 16 }}>
          <Tabs
            value={activeIndex}
            onChange={this.changeTab}
            TabIndicatorProps={{ style: { display: 'none' } }}
            textColor="inherit"
            variant="standard">
            {PAGE_TABS.map((tab, index) => (
              <Tab
                key={tab.key}
                icon={tab.icon}
                label={tab.label}
                style={{
                  fontWeight: 'bold',
                  color: activeIndex === index ? colors.accent : '',
                  borderBottom: activeIndex === index ? `3px solid ${colors.accent}` : '',
                }}
              />
            ))}
          </Tabs>
        </Paper>
        <PeopleCountCards
          show={['employees']}
          refreshKey={`${teacherList.length}-${workerList.length}`}
          extra={[
            { label: 'Teachers', value: teacherList.length, tone: 'good' },
            { label: 'Workers', value: workerList.length, tone: 'warn' },
          ]}
        />
        {activeTab === 'teachers' ? (
          <TeacherStaffPanel
            teacherList={teacherList}
            empSubjectList={empSubjectList}
            isCollapseOpen={this.state.isCollapseOpen}
            isEmpAssignFetching={this.state.isEmpAssignFetching}
            isLoading={this.state.employeesFetching}
            onAdd={() => this.openAddModal('TEACHING')}
            onEdit={this.openEditModal}
            onFetchViewData={this.fetchEmployeeAssignedSubjects}
            onImport={this.importModalOpen}
          />
        ) : (
          <WorkerStaffPanel
            workerList={workerList}
            isLoading={this.state.workersFetching}
            onAdd={() => this.openAddModal('NON_TEACHING')}
            onEdit={this.openEditModal}
            onDelete={this.deleteWorker}
          />
        )}
        <EmployeeFormModal
          isModalOpen={this.state.isModalOpen}
          formModalCloseProp={this.closeModal}
          saveEmployee={this.saveEmployee}
          employee={this.state.editingEmployee}
          defaultProfession={this.state.formDefaultProfession}
          updateEmployee={this.updateEmployee}
          employeeUpdateSuccess={this.employeeUpdateSuccess}
        />
        <ImportEmployeesModal
          isImportEmployeesModalOpen={this.state.isImportModalOpen}
          formModalClose={this.importModalClose}
          uploadData={this.uploadEmployeesData}
          uploadSuccess={this.uploadSuccess}
          scrollToTop={() => window.scrollTo(0, 0)}
        />
      </div>
    );
  }
}

const mapStateToProps = state => ({
  loggedUserToken: state.auth.loggedUserToken,
  employee: state.employees.employee,
  empSubjectList: state.subjects.empSubjectList,
});

const mapDispatchToProps = dispatch => ({
  saveEmployee: data => dispatch(saveEmployeeService(data)),
  fetchEmployee: data => dispatch(fetchEmployeeService(data)),
  updateEmployee: data => dispatch(updateEmployeeService(data)),
  deleteEmployee: data => dispatch(deleteEmployeeService(data)),
  fetchEmployeeSubjects: data => dispatch(fetchEmployeeSubjectsService(data)),
  uploadEmployeesData: data => dispatch(uploadDataService(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(SchoolStaffHubPage);
