import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import validator from 'validator';
import DatePicker from 'react-datepicker';
import Select from 'react-select';
import CustomButton from '../../../../components/CustomButton';
import CustomCheckbox from '../../../../components/CustomCheckbox';
import { languages } from '../../Guardian/components/GuardianFormModal';
import { employeeStatic } from '../../../../config/constants';
import { sub } from 'date-fns';
import { formResMessage, toLoginEmail } from 'utils/commonFunc';

const blankData = () => ({
  employeeId: 0,
  name: '',
  email: '',
  gender: '',
  dateOfBirth: '',
  qualification: '',
  phoneNumber: '',
  joiningDateTime: '',
  designation: '',
  department: '',
  profession: 'TEACHING',
  totalExperience: '',
  code: new Date().getTime(),
  status: 'ACTIVE',
  motherTongue: '',
  employerOrgId: 0,
});

class EmployeeFormModal extends React.Component {
  // defaultProfession lets a caller (e.g. the Workers panel) open this same modal pre-set to
  // NON_TEACHING for a brand-new record - re-read at reset time (not just at construction) so it
  // stays correct even though one modal instance is shared across Teacher/Worker "Add" clicks.
  getBlankState = () => ({
    data: { ...blankData(), profession: this.props.defaultProfession || 'TEACHING' },
    errors: {},
    loading: false,
  });

  state = this.getBlankState();

  handleChange = e =>
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });

  handleCheckChange = e => {
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.id },
    });
  };

  // handleSelectChange = (name, selectItem) => {
  //   this.setState({
  //     data: {
  //       ...this.state.data,
  //       [name]: selectItem.value,
  //     }
  //   })
  // }

  handleDateChange = (name, date) => {
    if (date) {
      this.setState({
        data: {
          ...this.state.data,
          [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
        },
      });
    } else {
      this.setState({ data: { ...this.state.data, [name]: null } });
    }
  };

  handleSelectChange = (name, selectItem) => {
    this.setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectItem.value,
      },
    }));
  };

  componentDidUpdate(prevProps) {
    if (this.props.employee && prevProps.employee !== this.props.employee) {
      const { employee } = this.props;
      this.setState({
        data: {
          employeeId: employee?.employeeId,
          name: employee.name,
          email: employee.email,
          gender: employee.gender,
          dateOfBirth: employee.dateOfBirth,
          qualification: employee.qualification,
          joiningDateTime: employee.joiningDateTime,
          designation: employee.designation,
          department: employee.department,
          profession: employee.profession || 'TEACHING',
          totalExperience: employee.totalExperience,
          code: employee.code,
          status: 'ACTIVE',
          motherTongue: employee.motherTongue,
          employerOrgId: employee?.employerOrgId,
          phoneNumber: employee?.phoneNumber,
        },
        loading: false,
        errors: {},
      });
    } else if (!prevProps.isModalOpen && this.props.isModalOpen && !this.props.employee) {
      // Opened fresh for "Add" (no employee to populate from) - one modal instance is reused
      // across Teacher/Worker Add clicks, so re-apply whatever defaultProfession applies now.
      this.setState(this.getBlankState());
    }
  }

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (Object.keys(errors).length === 0) {
      this.setState({ loading: true });
      // data.phoneNumber = data.mobileNumber;
      const payload = { ...data, email: toLoginEmail(data.email) };
      if (data.employeeId) {
        this.props
          .updateEmployee(payload)
          .then(() => {
            this.stateReset();
            this.props.employeeUpdateSuccess('update');
          })
          .catch(err => this.setError(err));
      } else {
        this.props
          .saveEmployee(payload)
          .then(() => {
            this.stateReset();
            this.props.employeeUpdateSuccess('add');
          })
          .catch(err => this.setError(err));
      }
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(this.getBlankState());
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};
    // if (!data.code) {
    //   errors.code = `${employeeStatic} code cannot be empty`;
    // }
    if (!data.name) {
      errors.name = 'Name cannot be empty';
    }
    if (!data.email) {
      errors.email = 'Email cannot be empty';
    } else if (!validator.isEmail(toLoginEmail(data.email))) {
      errors.email = 'Invalid email';
    }
    if (!data.phoneNumber) {
      errors.phoneNumber = 'Phone number cannot be empty';
    } else if (!validator.isMobilePhone(data.phoneNumber)) {
      errors.phoneNumber = 'Invalid phone number';
    }
    if (!data.gender) {
      errors.gender = 'Gender cannot be empty';
    }
    if (!data.dateOfBirth) {
      errors.dateOfBirth = 'Date of birth cannot be empty';
    } else if (moment(data.dateOfBirth) > moment().subtract(21, 'years')) {
      errors.dateOfBirth = 'Invalid date of birth, Minimum age should be 21';
    }
    if (!data.qualification) {
      errors.qualification = 'Qualification cannot be empty';
    }
    if (!data.joiningDateTime) {
      errors.joiningDateTime = 'Joining date cannot be empty';
    } else if (data.dateOfBirth >= data.joiningDateTime) {
      errors.joiningDateTime = "Joining date shouldn't be less than or equal to the Date of birth";
    }
    if (!data.designation) {
      errors.designation = 'Designation type cannot be empty';
    }
    if (!data.department) {
      errors.department = 'Department type cannot be empty';
    }
    if (!data.totalExperience) {
      errors.totalExperience = 'Total experience cannot be empty';
    }
    if (!data.motherTongue?.toString().trim()) {
      errors.motherTongue = 'Mother Tongue cannot be empty';
    }
    return errors;
  };

  render() {
    const { isModalOpen } = this.props;
    const { data, errors, loading } = this.state;
    // "Teacher" is the school's configurable label (employeeStatic); "Worker" isn't config-backed
    // since School Staffs (where the Workers tab lives) intentionally doesn't map to that config.
    const roleLabel = data.profession === 'NON_TEACHING' ? 'WORKER' : employeeStatic.toUpperCase();
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>{data?.employeeId ? `UPDATE ${roleLabel}` : `ADD ${roleLabel}`}</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={6}>
                    {/* <FormGroup>
                      <Label htmlFor="">
                        {employeeStatic} code<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="code"
                        onChange={this.handleChange}
                        value={data.code}
                        placeholder="Enter here..."
                        maxLength="50"
                        disabled={data?.employeeId}
                      />
                      {errors.code && <span className="err-msg">{errors.code}</span>}
                    </FormGroup> */}
                    <FormGroup>
                      <Label htmlFor="">
                        Name<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="name"
                        onChange={this.handleChange}
                        value={data.name}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.name && <span className="err-msg">{errors.name}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Username or Email<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="email"
                        onChange={this.handleChange}
                        value={data.email}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.email && <span className="err-msg">{errors.email}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Phone number<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="phoneNumber"
                        onChange={this.handleChange}
                        value={data.phoneNumber}
                        placeholder="E.g: +91-9876... or 98765..."
                        maxLength="15"
                      />
                      {errors.phoneNumber && <span className="err-msg">{errors.phoneNumber}</span>}
                    </FormGroup>
                    <FormGroup style={{ marginTop: 15, marginBottom: 20 }}>
                      <Label for="exampleCheckbox">Gender</Label>
                      <Row>
                        <Col sm={3}>
                          <CustomCheckbox
                            value={data.gender}
                            id="MALE"
                            name="gender"
                            label="Male"
                            onChange={this.handleCheckChange}
                            checked={data.gender === 'MALE'}
                          />
                        </Col>
                        <Col sm={3}>
                          <CustomCheckbox
                            value={data.gender}
                            id="FEMALE"
                            name="gender"
                            label="Female"
                            onChange={this.handleCheckChange}
                            checked={data.gender === 'FEMALE'}
                          />
                        </Col>
                      </Row>
                      {errors.gender && <span className="err-msg">{errors.gender}</span>}
                    </FormGroup>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        Date of Birth<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.dateOfBirth ? new Date(data.dateOfBirth) : null}
                        onChange={value => this.handleDateChange('dateOfBirth', value)}
                        dateFormat="dd/MM/yyyy"
                        showMonthDropdown
                        showYearDropdown
                        placeholderText="Select date..."
                        maxDate={sub(new Date(), { years: 2 })}
                        dropdownMode="select"
                      />
                      {errors.dateOfBirth && <span className="err-msg">{errors.dateOfBirth}</span>}
                    </FormGroup>
                  </Col>
                  <Col sm={6}>
                    <FormGroup>
                      <Label htmlFor="">
                        Qualification<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="qualification"
                        onChange={this.handleChange}
                        value={data.qualification}
                        placeholder="E.g: Engineerning, Bachelor degree"
                        maxLength="50"
                      />
                      {errors.qualification && <span className="err-msg">{errors.qualification}</span>}
                    </FormGroup>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        Joining date<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.joiningDateTime ? new Date(data.joiningDateTime) : null}
                        onChange={value => this.handleDateChange('joiningDateTime', value)}
                        dateFormat="dd/MM/yyyy"
                        showMonthDropdown
                        showYearDropdown
                        placeholderText="Select date..."
                        maxDate={new Date()}
                        dropdownMode="select"
                      />
                      {errors.joiningDateTime && <span className="err-msg">{errors.joiningDateTime}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Designation<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="designation"
                        onChange={this.handleChange}
                        value={data.designation}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.designation && <span className="err-msg">{errors.designation}</span>}
                    </FormGroup>
                    <FormGroup style={{ marginTop: 15, marginBottom: 20 }}>
                      <Label for="exampleCheckbox">
                        Profession
                        <sup> *</sup>
                      </Label>
                      <Row>
                        <Col sm={6}>
                          <CustomCheckbox
                            value={data.profession}
                            id="TEACHING"
                            name="profession"
                            label="Teaching"
                            onChange={this.handleCheckChange}
                            checked={data.profession === 'TEACHING'}
                          />
                        </Col>
                        <Col sm={6}>
                          <CustomCheckbox
                            value={data.profession}
                            id="NON_TEACHING"
                            name="profession"
                            label="Non-teaching"
                            onChange={this.handleCheckChange}
                            checked={data.profession === 'NON_TEACHING'}
                          />
                        </Col>
                      </Row>
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Department<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="department"
                        onChange={this.handleChange}
                        value={data.department}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.department && <span className="err-msg">{errors.department}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Total experience<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="totalExperience"
                        onChange={this.handleChange}
                        value={data.totalExperience}
                        placeholder="E.g: 1 year 2 months"
                        maxLength="50"
                      />
                      {errors.totalExperience && <span className="err-msg">{errors.totalExperience}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Select Mother Tongue or Native Language<sup> *</sup>
                      </Label>
                      <Select
                        value={data.motherTongue ? languages.find(dt => dt.value === data.motherTongue) : null}
                        onChange={value => this.handleSelectChange('motherTongue', value)}
                        options={languages}
                      />
                      {errors.motherTongue && <span className="err-msg">{errors.motherTongue}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default EmployeeFormModal;
